// This file is generated by AI.

// 配音编辑模式的可见性与推进规则测试。
//
// 这些规则直接决定用户会不会"在不该看到麦克风的地方看到麦克风":
// * 工作台关闭时, 任何场景卡都不显示配音开关;
// * 工作台打开时, 当前场景卡自动进入配音编辑模式, 切换场景卡同样自动进入;
// * 关闭工作台即整体退出。

import { beforeEach, describe, expect, it } from 'vitest';

import { useAppStore } from '../src/state/store';
import { makeSceneTab } from '../src/tabs/model';
import { activeSceneInVoiceMode, isSceneInVoiceMode, setSceneVoiceMode, toggleVoiceWorkbench } from '../src/voice/mode';

const sceneA = 'C:\\project\\game\\scene\\a.txt';
const sceneB = 'C:\\project\\game\\scene\\b.txt';

function resetStore(): void {
  useAppStore.setState({
    tabs: [],
    activeTabId: null,
    documents: [],
    voiceWorkbenchOpen: false,
    voiceModePaths: [],
  });
  for (const path of [sceneA, sceneB]) {
    useAppStore.getState().openDocument({
      path,
      name: path.split('\\').pop() ?? path,
      uri: `file:///${path}`,
      content: '爱音:台词;\n',
      dirty: false,
      isScene: true,
    });
  }
}

describe('配音编辑模式的可见性', () => {
  beforeEach(resetStore);

  it('未打开工作台时任何场景都不在配音编辑模式', () => {
    useAppStore.getState().openTab(makeSceneTab(sceneA, 'a.txt'));
    useAppStore.getState().openTab(makeSceneTab(sceneB, 'b.txt'));
    expect(isSceneInVoiceMode(sceneA)).toBe(false);
    expect(isSceneInVoiceMode(sceneB)).toBe(false);
    expect(activeSceneInVoiceMode()).toBe(false);
  });

  it('打开工作台后当前场景已就位 (切回它即是配音编辑模式)', () => {
    const sceneTabA = makeSceneTab(sceneA, 'a.txt');
    useAppStore.getState().openTab(sceneTabA);
    toggleVoiceWorkbench();

    expect(useAppStore.getState().voiceWorkbenchOpen).toBe(true);
    // 打开工作台后活动项是工作台本身 (它取代工作区), 因此此处没有"活动场景"
    expect(isSceneInVoiceMode(sceneA)).toBe(true);

    // 切回场景卡即进入配音编辑模式
    useAppStore.getState().activateTab(sceneTabA.id);
    expect(activeSceneInVoiceMode()).toBe(true);
  });

  it('配音工作台打开时, 切换场景卡不会改变已就位的场景', () => {
    const sceneTabA = makeSceneTab(sceneA, 'a.txt');
    const sceneTabB = makeSceneTab(sceneB, 'b.txt');
    useAppStore.getState().openTab(sceneTabA);
    useAppStore.getState().openTab(sceneTabB);
    // 此刻活动项是 B
    toggleVoiceWorkbench();
    expect(isSceneInVoiceMode(sceneB)).toBe(true);
    // A 是此前打开过但未激活的场景, 不应被误开启
    expect(isSceneInVoiceMode(sceneA)).toBe(false);

    useAppStore.getState().activateTab(sceneTabA.id);
    expect(activeSceneInVoiceMode()).toBe(true);
  });

  it('工作台打开期间切换场景卡, 目标场景卡也自动进入', () => {
    useAppStore.getState().openTab(makeSceneTab(sceneA, 'a.txt'));
    toggleVoiceWorkbench();
    const tabB = useAppStore.getState().tabs.find((tab) => tab.kind === 'scene' && tab.path === sceneB);
    // B 尚未打开, 先打开它 (打开即激活)
    useAppStore.getState().openTab(makeSceneTab(sceneB, 'b.txt'));
    expect(isSceneInVoiceMode(sceneB)).toBe(true);
    expect(tabB).toBeUndefined();

    // 切回 A 仍然是配音编辑模式
    const tabA = useAppStore.getState().tabs.find((tab) => tab.kind === 'scene' && tab.path === sceneA);
    useAppStore.getState().activateTab(tabA!.id);
    expect(activeSceneInVoiceMode()).toBe(true);
  });

  it('关闭工作台后全部退出配音编辑模式', () => {
    useAppStore.getState().openTab(makeSceneTab(sceneA, 'a.txt'));
    toggleVoiceWorkbench();
    expect(isSceneInVoiceMode(sceneA)).toBe(true);

    toggleVoiceWorkbench();
    expect(useAppStore.getState().voiceWorkbenchOpen).toBe(false);
    expect(isSceneInVoiceMode(sceneA)).toBe(false);
    expect(useAppStore.getState().voiceModePaths).toEqual([]);
  });

  it('可以手动关闭单个场景的配音编辑模式', () => {
    useAppStore.getState().openTab(makeSceneTab(sceneA, 'a.txt'));
    toggleVoiceWorkbench();
    setSceneVoiceMode(sceneA, false);
    expect(isSceneInVoiceMode(sceneA)).toBe(false);
    // 但切走再切回不应被自动重新开启 —— 尊重用户的显式选择
    const tabB = makeSceneTab(sceneB, 'b.txt');
    useAppStore.getState().openTab(tabB);
    expect(isSceneInVoiceMode(sceneB)).toBe(true);
    const tabA = useAppStore.getState().tabs.find((tab) => tab.kind === 'scene' && tab.path === sceneA);
    useAppStore.getState().activateTab(tabA!.id);
    expect(isSceneInVoiceMode(sceneA)).toBe(false);
  });

  it('工作台关闭时切换场景卡不会开启配音编辑模式', () => {
    useAppStore.getState().openTab(makeSceneTab(sceneA, 'a.txt'));
    useAppStore.getState().openTab(makeSceneTab(sceneB, 'b.txt'));
    const tabA = useAppStore.getState().tabs.find((tab) => tab.kind === 'scene' && tab.path === sceneA);
    useAppStore.getState().activateTab(tabA!.id);
    expect(useAppStore.getState().voiceModePaths).toEqual([]);
  });
});
